css:
/* @prim:begin 54-signal-ledger */
.sl{container-type:inline-size;min-width:0;display:flex;flex-direction:column;gap:28px}
.sl > *{margin:0}
.sl-group{min-width:0}
.sl-gh{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding:0 0 10px;border-bottom:1px solid var(--border)}
.sl-gh .section-label{margin:0}
.sl-gn{font-family:var(--ds-font-mono);font-size:var(--fs-label);letter-spacing:.08em;color:var(--text-secondary)}
.sl-rows{list-style:none;margin:0;padding:0}
.sl-group.is-judgment .sl-rows{border-left:2px solid var(--gold);padding-left:14px}
.sl-row{display:grid;grid-template-columns:minmax(0,1fr);gap:6px 20px;align-items:start;padding:14px 0;border-bottom:1px solid var(--border)}
.sl-row:last-child{border-bottom:0}
.sl-key{display:flex;flex-direction:column;align-items:flex-start;gap:6px;min-width:0}
.sl-key .chip{flex:none;white-space:nowrap}
.sl-sig{font-family:var(--ds-font-mono);font-size:var(--fs-body);font-weight:600;letter-spacing:.02em;line-height:1.45;color:var(--text-secondary);min-width:0}
.sl-ev{margin:0;min-width:0;line-height:1.55;color:var(--text);text-wrap:pretty}
@container (min-width:38rem){.sl-row{grid-template-columns:minmax(10rem,14rem) minmax(0,1fr)}.sl-key{flex-direction:column;align-items:flex-start}}
@container (min-width:58rem){.sl-row{grid-template-columns:10rem minmax(9rem,13rem) minmax(0,1fr)}.sl-key{display:contents}.sl-key .chip{justify-self:start}}
/* @prim:end 54-signal-ledger */

demo:
function slEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
var SLG=[{label:'Observed',rows:[['Bull','plain','Transaction counts (leading, noisy)','165M agent transactions by April, about half of them tests.'],['Bear','plain','Volume, tests removed','Near $1.6M a month on the strictest filter.'],['Rules','cyan','Regulatory calendar','The stablecoin rule takes effect 2027-01-18.']]},{label:'My judgment',judgment:true,rows:[['Call','gold','Enter small, before the rule','My read: 1 in 3 by 2027-06-30. I will post the outcome either way.']]}];
function kitSignalLedger(host,groups){var w=document.createElement('div');w.className='sl';w.innerHTML=groups.map(function(g,gi){var id='slg-'+Math.random().toString(36).slice(2,8);return '<section class="sl-group'+(g.judgment?' is-judgment':'')+'" aria-labelledby="'+id+'"><div class="sl-gh"><h3 class="section-label" id="'+id+'">'+slEsc(g.label)+'</h3><span class="sl-gn">'+g.rows.length+(g.rows.length===1?' row':' rows')+'</span></div><ul class="sl-rows">'+g.rows.map(function(r){return '<li class="sl-row"><div class="sl-key"><span class="chip'+(r[1]&&r[1]!=='plain'?' '+r[1]:'')+'">'+slEsc(r[0])+'</span><span class="sl-sig">'+slEsc(r[2])+'</span></div><p class="sl-ev">'+slEsc(r[3])+'</p></li>'}).join('')+'</ul></section>'}).join('');host.appendChild(w);return w}
kitSignalLedger(kSlot(),SLG);
document.querySelectorAll('[data-state]').forEach(function(el,i){var a=STATES[i];var g=a[0]==='one'?[SLG[0]]:SLG;var box=document.createElement('div');box.style.maxWidth=a[1];el.appendChild(box);kitSignalLedger(box,g)});
function kSlot(){return document.querySelector('[data-stage]')}
